sql.where:
al.tenant_id = #{tenantId}
AND al.module = #{module}
AND al.action = #{action}

    AND  = #{riskLevel}



    AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(al.detail_json) THEN al.detail_json ELSE '{}' END, '$.actorType')), 'HUMAN') = #{actorType}

AND al.actor_id = #{actorId}
AND al.target_type = #{targetType}
AND al.target_id = #{targetId}
AND al.gmt_create >= #{startTime}
AND al.gmt_create <= #{endTime}
AND al.detail_json LIKE CONCAT('%', #{keyword}, '%')
